insert into public.hospitals (hospital_id, slug, name, name_spoken_te, name_spoken_hi, name_aliases, area_id, type, address, rating, highlight, specialities, facilities, opd_hours, languages_spoken, faqs, phone, accent_color, is_sample_data) values
  ('h_jh_01', 'merugu-grove-hospital-jubilee-hills', 'Merugu Grove Hospital', 'మెరుగు గ్రోవ్ హాస్పిటల్', 'मेरुगु ग्रोव हॉस्पिटल', array['Merugu Grove', 'Merugu', 'Merugu Grov']::text[], 'jubilee_hills', 'multi-speciality hospital', 'Lime Finch Junction, Jubilee Hills', 4.6, 'An outpatient desk coordinates appointments across seven departments.', array['General Medicine', 'Dermatology', 'Pediatrics', 'Orthopedics', 'ENT', 'Cardiology', 'Gynecology']::text[], '{"emergency_24x7": true, "pharmacy": true, "lab": true, "ambulance": true, "cashless_insurance": true, "wheelchair_access": true}'::jsonb, '{"mon": "09:00-20:00", "tue": "09:00-20:00", "wed": "09:00-20:00", "thu": "09:00-20:00", "fri": "09:00-20:00", "sat": "09:00-19:30", "sun": "09:00-18:15"}'::jsonb, array['Telugu', 'Hindi', 'English']::text[], '[{"q": "What are the Sunday appointment hours?", "a_en": "The Sunday OPD runs from 09:00 to 18:15. Appointment times depend on the doctor.", "a_te": "ఆదివారం ఓపీడీ 09:00 నుంచి 18:15 వరకు ఉంటుంది. అపాయింట్‌మెంట్ టైమ్ డాక్టర్ షెడ్యూల్ బట్టి ఉంటుంది.", "a_hi": "रविवार को ओपीडी 09:00 से 18:15 तक खुली है। अपॉइंटमेंट का समय डॉक्टर के शेड्यूल पर है।"}, {"q": "How much is the consultation fee?", "a_en": "The sample fee varies by doctor. Tell me the doctor''s name and I can look it up.", "a_te": "డెమో కన్సల్టేషన్ ఫీజు డాక్టర్‌ని బట్టి మారుతుంది. పేరు చెప్తే చెక్ చేస్తాను.", "a_hi": "डेमो कंसल्टेशन फ़ीस डॉक्टर के हिसाब से है। नाम बताएँ, मैं देख लेता हूँ।"}, {"q": "Is there a lab at this location?", "a_en": "Yes, there is a lab on site.", "a_te": "అవును, ఇక్కడే ల్యాబ్ ఉంది.", "a_hi": "हाँ, यहाँ लैब है।"}, {"q": "Is there wheelchair access?", "a_en": "Yes, the OPD entrance has wheelchair access.", "a_te": "అవును, ఓపీడీకి వీల్‌చైర్‌తో వెళ్లొచ్చు.", "a_hi": "हाँ, व्हीलचेयर से ओपीडी में जा सकते हैं।"}]'::jsonb, 'DEMO-H-001', '#BE123C', true),
  ('h_jh_02', 'nila-sopanam-hospital-jubilee-hills', 'Nila Sopanam Hospital', 'నీల సోపానం హాస్పిటల్', 'नीला सोपानम हॉस्पिटल', array['Nila Sopanam', 'Neela Sopanam', 'Sopanam Hospital']::text[], 'jubilee_hills', 'multi-speciality hospital', 'Porcelain Kite Court, Jubilee Hills', 4.5, 'Has scheduled eye and dental clinics alongside general outpatient care.', array['General Medicine', 'Ophthalmology', 'Dental', 'Dermatology', 'Orthopedics', 'Cardiology']::text[], '{"emergency_24x7": true, "pharmacy": true, "lab": true, "ambulance": true, "cashless_insurance": false, "wheelchair_access": true}'::jsonb, '{"mon": "09:00-19:30", "tue": "09:00-19:30", "wed": "09:00-19:30", "thu": "09:00-19:30", "fri": "09:00-19:30", "sat": "09:00-19:00", "sun": "09:00-18:00"}'::jsonb, array['Telugu', 'Hindi', 'English']::text[], '[{"q": "What are the Sunday appointment hours?", "a_en": "The Sunday OPD runs from 09:00 to 18:00. Appointment times depend on the doctor.", "a_te": "ఆదివారం ఓపీడీ 09:00 నుంచి 18:00 వరకు ఉంటుంది. అపాయింట్‌మెంట్ టైమ్ డాక్టర్ షెడ్యూల్ బట్టి ఉంటుంది.", "a_hi": "रविवार को ओपीडी 09:00 से 18:00 तक खुली है। अपॉइंटमेंट का समय डॉक्टर के शेड्यूल पर है।"}, {"q": "How much is the consultation fee?", "a_en": "The sample fee varies by doctor. Tell me the doctor''s name and I can look it up.", "a_te": "డెమో కన్సల్టేషన్ ఫీజు డాక్టర్‌ని బట్టి మారుతుంది. పేరు చెప్తే చెక్ చేస్తాను.", "a_hi": "डेमो कंसल्टेशन फ़ीस डॉक्टर के हिसाब से है। नाम बताएँ, मैं देख लेता हूँ।"}, {"q": "Is there a lab at this location?", "a_en": "Yes, there is a lab on site.", "a_te": "అవును, ఇక్కడే ల్యాబ్ ఉంది.", "a_hi": "हाँ, यहाँ लैब है।"}, {"q": "Is there wheelchair access?", "a_en": "Yes, the OPD entrance has wheelchair access.", "a_te": "అవును, ఓపీడీకి వీల్‌చైర్‌తో వెళ్లొచ్చు.", "a_hi": "हाँ, व्हीलचेयर से ओपीडी में जा सकते हैं।"}]'::jsonb, 'DEMO-H-002', '#4338CA', true),
  ('h_jh_03', 'tarali-skin-and-eye-clinic-jubilee-hills', 'Tarali Skin and Eye Clinic', 'తరళి స్కిన్ అండ్ ఐ క్లినిక్', 'तरलि स्किन ऐंड आई क्लिनिक', array['Tarali Skin and Eye', 'Tarali Clinic', 'Taralee Clinic']::text[], 'jubilee_hills', 'clinic', 'Violet Loom Walk, Jubilee Hills', 4.8, 'A small clinic with separate dermatology and eye appointment sessions.', array['Dermatology', 'Ophthalmology']::text[], '{"emergency_24x7": false, "pharmacy": false, "lab": false, "ambulance": false, "cashless_insurance": false, "wheelchair_access": true}'::jsonb, '{"mon": "09:30-19:00", "tue": "09:30-19:00", "wed": "09:30-19:00", "thu": "09:30-19:00", "fri": "09:30-19:00", "sat": "09:30-18:30", "sun": "09:30-18:00"}'::jsonb, array['Telugu', 'English']::text[], '[{"q": "What are the Sunday appointment hours?", "a_en": "The Sunday OPD runs from 09:30 to 18:00. Appointment times depend on the doctor.", "a_te": "ఆదివారం ఓపీడీ 09:30 నుంచి 18:00 వరకు ఉంటుంది. అపాయింట్‌మెంట్ టైమ్ డాక్టర్ షెడ్యూల్ బట్టి ఉంటుంది.", "a_hi": "रविवार को ओपीडी 09:30 से 18:00 तक खुली है। अपॉइंटमेंट का समय डॉक्टर के शेड्यूल पर है।"}, {"q": "How much is the consultation fee?", "a_en": "The sample fee varies by doctor. Tell me the doctor''s name and I can look it up.", "a_te": "డెమో కన్సల్టేషన్ ఫీజు డాక్టర్‌ని బట్టి మారుతుంది. పేరు చెప్తే చెక్ చేస్తాను.", "a_hi": "डेमो कंसल्टेशन फ़ीस डॉक्टर के हिसाब से है। नाम बताएँ, मैं देख लेता हूँ।"}, {"q": "Is there a lab at this location?", "a_en": "There is no on-site lab.", "a_te": "ఇక్కడ ల్యాబ్ లేదు.", "a_hi": "यहाँ लैब नहीं है।"}, {"q": "Is there wheelchair access?", "a_en": "Yes, the OPD entrance has wheelchair access.", "a_te": "అవును, ఓపీడీకి వీల్‌చైర్‌తో వెళ్లొచ్చు.", "a_hi": "हाँ, व्हीलचेयर से ओपीडी में जा सकते हैं।"}]'::jsonb, 'DEMO-H-003', '#0369A1', true),
  ('h_jh_04', 'velugu-nest-clinic-jubilee-hills', 'Velugu Nest Clinic', 'వెలుగు నెస్ట్ క్లినిక్', 'वेलुगु नेस्ट क्लिनिक', array['Velugu Nest', 'Velugu Clinic', 'Velugu Next Clinic']::text[], 'jubilee_hills', 'clinic', 'Rainwood Corner, Jubilee Hills', 4.4, 'A neighbourhood clinic with appointments for children and adults.', array['Pediatrics', 'General Medicine', 'ENT']::text[], '{"emergency_24x7": false, "pharmacy": false, "lab": true, "ambulance": false, "cashless_insurance": false, "wheelchair_access": true}'::jsonb, '{"mon": "09:00-19:30", "tue": "09:00-19:30", "wed": "09:00-19:30", "thu": "09:00-19:30", "fri": "09:00-19:30", "sat": "09:00-19:00", "sun": "09:00-18:00"}'::jsonb, array['Telugu', 'Hindi', 'English']::text[], '[{"q": "What are the Sunday appointment hours?", "a_en": "The Sunday OPD runs from 09:00 to 18:00. Appointment times depend on the doctor.", "a_te": "ఆదివారం ఓపీడీ 09:00 నుంచి 18:00 వరకు ఉంటుంది. అపాయింట్‌మెంట్ టైమ్ డాక్టర్ షెడ్యూల్ బట్టి ఉంటుంది.", "a_hi": "रविवार को ओपीडी 09:00 से 18:00 तक खुली है। अपॉइंटमेंट का समय डॉक्टर के शेड्यूल पर है।"}, {"q": "How much is the consultation fee?", "a_en": "The sample fee varies by doctor. Tell me the doctor''s name and I can look it up.", "a_te": "డెమో కన్సల్టేషన్ ఫీజు డాక్టర్‌ని బట్టి మారుతుంది. పేరు చెప్తే చెక్ చేస్తాను.", "a_hi": "डेमो कंसल्टेशन फ़ीस डॉक्टर के हिसाब से है। नाम बताएँ, मैं देख लेता हूँ।"}, {"q": "Is there a lab at this location?", "a_en": "Yes, there is a lab on site.", "a_te": "అవును, ఇక్కడే ల్యాబ్ ఉంది.", "a_hi": "हाँ, यहाँ लैब है।"}, {"q": "Is there wheelchair access?", "a_en": "Yes, the OPD entrance has wheelchair access.", "a_te": "అవును, ఓపీడీకి వీల్‌చైర్‌తో వెళ్లొచ్చు.", "a_hi": "हाँ, व्हीलचेयर से ओपीडी में जा सकते हैं।"}]'::jsonb, 'DEMO-H-004', '#6D28D9', true),
  ('h_jh_05', 'malle-vaidya-family-clinic-jubilee-hills', 'Malle Vaidya Family Clinic', 'మల్లె వైద్య ఫ్యామిలీ క్లినిక్', 'मल्ले वैद्य फ़ैमिली क्लिनिक', array['Malle Vaidya', 'Malle Vaidya Clinic', 'Mallay Vaidya']::text[], 'jubilee_hills', 'clinic', 'Ivory Lattice Loop, Jubilee Hills', 4.1, 'Schedules general medicine, dental, and gynecology consultations.', array['Gynecology', 'Dental', 'General Medicine']::text[], '{"emergency_24x7": false, "pharmacy": true, "lab": false, "ambulance": false, "cashless_insurance": false, "wheelchair_access": false}'::jsonb, '{"mon": "09:00-19:30", "tue": "09:00-19:30", "wed": "09:00-19:30", "thu": "09:00-19:30", "fri": "09:00-19:30", "sat": "09:00-19:00", "sun": "09:00-18:00"}'::jsonb, array['Telugu', 'English']::text[], '[{"q": "What are the Sunday appointment hours?", "a_en": "The Sunday OPD runs from 09:00 to 18:00. Appointment times depend on the doctor.", "a_te": "ఆదివారం ఓపీడీ 09:00 నుంచి 18:00 వరకు ఉంటుంది. అపాయింట్‌మెంట్ టైమ్ డాక్టర్ షెడ్యూల్ బట్టి ఉంటుంది.", "a_hi": "रविवार को ओपीडी 09:00 से 18:00 तक खुली है। अपॉइंटमेंट का समय डॉक्टर के शेड्यूल पर है।"}, {"q": "How much is the consultation fee?", "a_en": "The sample fee varies by doctor. Tell me the doctor''s name and I can look it up.", "a_te": "డెమో కన్సల్టేషన్ ఫీజు డాక్టర్‌ని బట్టి మారుతుంది. పేరు చెప్తే చెక్ చేస్తాను.", "a_hi": "डेमो कंसल्टेशन फ़ीस डॉक्टर के हिसाब से है। नाम बताएँ, मैं देख लेता हूँ।"}, {"q": "Is there a lab at this location?", "a_en": "There is no on-site lab.", "a_te": "ఇక్కడ ల్యాబ్ లేదు.", "a_hi": "यहाँ लैब नहीं है।"}, {"q": "Is there wheelchair access?", "a_en": "Wheelchair access is not listed for this clinic.", "a_te": "ఈ క్లినిక్‌లో వీల్‌చైర్ సదుపాయం లిస్ట్‌లో లేదు.", "a_hi": "इस क्लिनिक के लिए व्हीलचेयर की सुविधा सूची में नहीं है।"}]'::jsonb, 'DEMO-H-005', '#4D7C0F', true),
